class MarkupExample(Scene):
    def construct(self):
        text = MarkupText('Blue textiscool!"')
        self.add(text)

class MarkupElaborateExample(Scene):
    def construct(self):
        text = MarkupText(
            'اَ'
            'لْعَر'
            'َبِي'
            'َّة'
            'ُ'
        )
        self.add(text)

class ColorExample(Scene):
    def construct(self):
        text1 = MarkupText(
            f'all in redexcept this', color=RED
        )
        text2 = MarkupText("nice gradient", gradient=(BLUE, GREEN))
        text3 = MarkupText(
            'niceintermediategradient',
            gradient=(BLUE, GREEN),
        )
        text4 = MarkupText(
            'fl ligaturecausing troublehere'
        )
        text5 = MarkupText(
            'fl ligaturedefeatedwith offset'
        )
        text6 = MarkupText(
            'fl ligaturefloatinginside'
        )
        text7 = MarkupText(
            'fl ligaturefloatinginside'
        )
        group = VGroup(text1, text2, text3, text4, text5, text6, text7).arrange(DOWN)
        self.add(group)

